<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>长川银行 - 值得信赖的金融服务伙伴</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif; color: #2c3e50; line-height: 1.6; background: #fff; }
        a { text-decoration: none; color: inherit; }
        .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

        /* Header */
        .top-bar { background: #1a2a4a; color: #b8c6db; font-size: 13px; padding: 8px 0; }
        .top-bar .container { display: flex; justify-content: space-between; align-items: center; }
        .top-bar a { color: #b8c6db; margin-left: 16px; transition: color .2s; }
        .top-bar a:hover { color: #fff; }

        header { background: #fff; border-bottom: 1px solid #e8ecf1; position: sticky; top: 0; z-index: 1000; box-shadow: 0 2px 8px rgba(0,0,0,.06); }
        header .container { display: flex; align-items: center; justify-content: space-between; height: 72px; }
        .logo { display: flex; align-items: center; gap: 12px; }
        .logo-icon { width: 42px; height: 42px; background: linear-gradient(135deg, #1a5fb4, #2d8cf0); border-radius: 8px; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 20px; font-weight: 700; }
        .logo-text { font-size: 22px; font-weight: 700; color: #1a2a4a; }
        .logo-text span { color: #1a5fb4; }

        nav { display: flex; gap: 8px; }
        nav a { padding: 10px 18px; border-radius: 6px; font-size: 15px; font-weight: 500; color: #4a5568; transition: all .2s; }
        nav a:hover, nav a.active { background: #ebf3ff; color: #1a5fb4; }
        nav a.cta { background: #1a5fb4; color: #fff; }
        nav a.cta:hover { background: #1552a0; }

        /* Hero */
        .hero { background: linear-gradient(135deg, #0f2242 0%, #1a5fb4 100%); color: #fff; padding: 100px 0 80px; position: relative; overflow: hidden; }
        .hero::after { content: ''; position: absolute; top: -50%; right: -20%; width: 600px; height: 600px; border-radius: 50%; background: rgba(255,255,255,.03); }
        .hero .container { position: relative; z-index: 1; display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
        .hero h1 { font-size: 42px; font-weight: 700; line-height: 1.3; margin-bottom: 20px; }
        .hero p { font-size: 18px; color: #c5d5e8; margin-bottom: 36px; line-height: 1.8; }
        .hero-btns { display: flex; gap: 16px; }
        .btn { display: inline-block; padding: 14px 32px; border-radius: 8px; font-size: 16px; font-weight: 600; cursor: pointer; border: none; transition: all .2s; }
        .btn-primary { background: #2d8cf0; color: #fff; }
        .btn-primary:hover { background: #1a7ae0; transform: translateY(-1px); }
        .btn-outline { background: transparent; color: #fff; border: 2px solid rgba(255,255,255,.4); }
        .btn-outline:hover { border-color: #fff; background: rgba(255,255,255,.1); }
        .hero-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
        .stat-card { background: rgba(255,255,255,.08); backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,.12); border-radius: 12px; padding: 28px; }
        .stat-card .num { font-size: 32px; font-weight: 700; margin-bottom: 6px; }
        .stat-card .label { font-size: 14px; color: #a8bdd4; }

        /* Sections */
        .section { padding: 80px 0; }
        .section-header { text-align: center; margin-bottom: 56px; }
        .section-header h2 { font-size: 32px; font-weight: 700; color: #1a2a4a; margin-bottom: 12px; }
        .section-header p { font-size: 16px; color: #6b7c93; max-width: 560px; margin: 0 auto; }

        /* Services */
        .services-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
        .service-card { background: #fff; border: 1px solid #e8ecf1; border-radius: 12px; padding: 36px 28px; transition: all .3s; }
        .service-card:hover { box-shadow: 0 12px 40px rgba(26,95,180,.1); border-color: #b8d4f7; transform: translateY(-4px); }
        .service-icon { width: 56px; height: 56px; background: #ebf3ff; border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 26px; margin-bottom: 20px; }
        .service-card h3 { font-size: 18px; font-weight: 600; margin-bottom: 10px; color: #1a2a4a; }
        .service-card p { font-size: 14px; color: #6b7c93; line-height: 1.7; }
        .service-card a { display: inline-block; margin-top: 16px; font-size: 14px; color: #1a5fb4; font-weight: 500; }
        .service-card a:hover { text-decoration: underline; }

        /* Trust */
        .trust { background: #f6f9fc; }
        .trust-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; text-align: center; }
        .trust-item .num { font-size: 36px; font-weight: 700; color: #1a5fb4; }
        .trust-item .desc { font-size: 14px; color: #6b7c93; margin-top: 6px; }

        /* CTA Banner */
        .cta-banner { background: linear-gradient(135deg, #1a5fb4, #2d8cf0); padding: 64px 0; text-align: center; color: #fff; }
        .cta-banner h2 { font-size: 28px; margin-bottom: 12px; }
        .cta-banner p { font-size: 16px; color: #d0e3f8; margin-bottom: 28px; }
        .cta-banner .btn { background: #fff; color: #1a5fb4; }
        .cta-banner .btn:hover { background: #f0f7ff; }

        /* Footer */
        footer { background: #0f1c30; color: #8a9bb5; padding: 56px 0 28px; font-size: 14px; }
        footer .container { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 40px; }
        footer h4 { color: #fff; font-size: 15px; margin-bottom: 16px; }
        footer ul { list-style: none; }
        footer ul li { margin-bottom: 10px; }
        footer ul a { color: #8a9bb5; transition: color .2s; }
        footer ul a:hover { color: #fff; }
        .footer-bottom { border-top: 1px solid #1e3050; margin-top: 40px; padding-top: 24px; text-align: center; font-size: 13px; }

        /* Responsive */
        @media (max-width: 1024px) {
            .hero .container { grid-template-columns: 1fr; gap: 40px; }
            .services-grid { grid-template-columns: repeat(2, 1fr); }
            .trust-grid { grid-template-columns: repeat(2, 1fr); }
            footer .container { grid-template-columns: 1fr 1fr; }
        }
        @media (max-width: 768px) {
            .hero { padding: 60px 0; }
            .hero h1 { font-size: 30px; }
            .services-grid { grid-template-columns: 1fr; }
            nav { display: none; }
            .hero-btns { flex-direction: column; }
            .hero-stats { grid-template-columns: 1fr; }
        }
    </style>
</head>
<body>
