        nav a.cta { background: #1a5fb4; color: #fff; }
        nav a.cta:hover { background: #1552a0; }

        .page-hero { background: linear-gradient(135deg, #0f2242, #1a5fb4); color: #fff; padding: 72px 0 56px; }
        .page-hero h1 { font-size: 36px; font-weight: 700; margin-bottom: 12px; }
        .page-hero p { font-size: 16px; color: #c5d5e8; max-width: 600px; }
        .breadcrumb { font-size: 13px; color: #8ab0d8; margin-bottom: 20px; }
        .breadcrumb a:hover { color: #fff; }

        .section { padding: 72px 0; }
        .section-alt { background: #f6f9fc; }
        .section-header { margin-bottom: 48px; }
        .section-header h2 { font-size: 28px; font-weight: 700; color: #1a2a4a; margin-bottom: 8px; }
        .section-header p { font-size: 15px; color: #6b7c93; }

        .tabs { display: flex; gap: 4px; background: #eef2f7; border-radius: 10px; padding: 4px; margin-bottom: 36px; width: fit-content; }
        .tab { padding: 10px 24px; border-radius: 8px; font-size: 14px; font-weight: 500; cursor: pointer; transition: all .2s; border: none; background: transparent; color: #4a5568; }
        .tab.active { background: #fff; color: #1a5fb4; box-shadow: 0 2px 8px rgba(0,0,0,.08); }
        .tab:hover:not(.active) { color: #1a5fb4; }

        .product-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
        .product-card { background: #fff; border: 1px solid #e8ecf1; border-radius: 12px; padding: 32px; transition: all .3s; }
        .product-card:hover { box-shadow: 0 8px 32px rgba(26,95,180,.08); border-color: #b8d4f7; }
