        .product-card ul { list-style: none; margin-top: 16px; }
        .product-card ul li { font-size: 14px; color: #4a5568; padding: 6px 0; padding-left: 20px; position: relative; }
        .product-card ul li::before { content: '✓'; position: absolute; left: 0; color: #2d8cf0; font-weight: 700; }
        .product-card .btn { margin-top: 20px; display: inline-block; padding: 10px 24px; background: #1a5fb4; color: #fff; border-radius: 6px; font-size: 14px; font-weight: 500; transition: background .2s; }
        .product-card .btn:hover { background: #1552a0; }

        .loans-table { width: 100%; border-collapse: collapse; margin-top: 24px; }
        .loans-table th, .loans-table td { padding: 16px 20px; text-align: left; border-bottom: 1px solid #e8ecf1; font-size: 14px; }
        .loans-table th { background: #f6f9fc; font-weight: 600; color: #1a2a4a; }
        .loans-table td { color: #4a5568; }
        .loans-table .highlight { color: #1a5fb4; font-weight: 600; }

        .steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 40px; }
        .step { text-align: center; padding: 24px 16px; }
        .step-num { width: 44px; height: 44px; background: linear-gradient(135deg, #1a5fb4, #2d8cf0); color: #fff; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 18px; font-weight: 700; margin: 0 auto 14px; }
        .step h4 { font-size: 15px; font-weight: 600; margin-bottom: 6px; }
        .step p { font-size: 13px; color: #6b7c93; }

        .form-section { background: #fff; border: 1px solid #e8ecf1; border-radius: 12px; padding: 40px; max-width: 640px; margin: 0 auto; }
        .form-section h3 { font-size: 20px; font-weight: 600; margin-bottom: 24px; color: #1a2a4a; }
        .form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px; }
        .form-group { margin-bottom: 16px; }
        .form-group label { display: block; font-size: 14px; font-weight: 500; margin-bottom: 6px; color: #4a5568; }
        .form-group input, .form-group select, .form-group textarea { width: 100%; padding: 12px 14px; border: 1px solid #d1dce8; border-radius: 8px; font-size: 14px; font-family: inherit; transition: border-color .2s; }
        .form-group input:focus, .form-group select:focus, .form-group textarea:focus { outline: none; border-color: #1a5fb4; box-shadow: 0 0 0 3px rgba(26,95,180,.1); }
