    <script>
        function filterBranches() {
            const search = document.getElementById('branchSearch').value.toLowerCase();
            const region = document.getElementById('branchRegion').value;
            const branches = document.querySelectorAll('.branch-card');

            branches.forEach(card => {
                const city = card.getAttribute('data-city').toLowerCase();
                const cardRegion = card.getAttribute('data-region');
                const text = card.textContent.toLowerCase();

                const matchSearch = !search || text.includes(search);
                const matchRegion = !region || cardRegion === region;

                if (matchSearch && matchRegion) {
                    card.style.display = '';
                } else {
                    card.style.display = 'none';
                }
            });
        }
